import { forwardRef, type HTMLAttributes, type ReactNode } from 'react'
import { Navigation, Pause, Square } from '../../icons'
import { cn } from '../../lib/cn'
import type { VehicleStatusTone } from './VehiclePopupCard'
import { WEATHER_STATION_ART_48, WEATHER_STATION_ART_96 } from './weather-station-art'

/**
 * VehicleIcon3D — the 3D isometric vehicle illustration from the Live
 * Monitoring Figma (master art node 495:4149 "Car"; the list-row variant
 * 540:21613 is the same art scaled — identical 1.7647:1 aspect). Replaces
 * every photographic vehicle depiction (list rows, map markers, infowindow
 * card header) per the 2026-08-24 parity run's P0-1.
 *
 * EMBEDDED BRAND ASSET NOTE: the SVG art is illustration artwork extracted
 * from Figma, not themable UI styling — its internal colors are part of the
 * asset (like a logo), intentionally NOT tokens. Everything AROUND the art
 * (badge, rings) uses tokens.
 *
 * Anatomy per SPEC §2.2/P0-1:
 * - `size="sm"` → 39×29 outer box, art 38.8×22 centered with ~3.5px top
 *   offset (list-row thumb).
 * - `size="md"` → art at its master 57×32.33 (infowindow-card header tile).
 * - numeric `size` → art width in px, height keeps the master aspect
 *   (markers use ~26).
 * - `badge="start"` → 15×15 status dot overlapping the box's bottom-start
 *   (list anatomy); `badge="end"` → 16×16 dot at bottom-end (tile anatomy).
 *   Dot = status tone fill, white ring, white status glyph
 *   (arrow=success/moving · pause=warning/idling · square=error/stopped ·
 *   square=muted/non-reporting). Only rendered for a mobility-capable `art`
 *   (`MOBILITY_CAPABLE_ART`, below) — a stationary-asset art like
 *   `'weather-station'` never shows this dot, regardless of `badge`.
 */

export type VehicleIcon3DSize = 'sm' | 'md'

/**
 * Which illustration fills the box. Generic, config-driven per the DS's
 * "no business vocabulary hardcoded" rule (#10) — a consuming module picks
 * one via its own `uiConfig` (e.g. `map.vehicleArt` / `list.vehicleArt`),
 * this component just renders it. `'car'` (default) is the original Figma
 * master art (node 495:4149); `'tanker'` is a generic tank-truck
 * illustration for fleets whose assets are tankers, not passenger vehicles;
 * `'weather-station'` (A24) is a generic weather-mast illustration for
 * entity modules whose assets are stationary sensors, not vehicles at all —
 * a RASTER asset (`weather-station-art.ts`), unlike the two vector arts.
 */
export type VehicleIcon3DArt = 'car' | 'tanker' | 'weather-station'

/**
 * Art variants that depict an actual mobility-tracked vehicle — moving /
 * idling / stopped is a meaningful status for these, so the status badge
 * dot is allowed to render. `'weather-station'` (and any future stationary-
 * asset art) is deliberately left OUT: a static sensor has no mobility
 * status, so the badge must default OFF for it — enforced HERE, once, in the
 * shared primitive, rather than left to every caller to remember. A caller
 * asking for `badge` on a non-mobility art is silently ignored (see the
 * render below) rather than special-cased per module.
 */
const MOBILITY_CAPABLE_ART = new Set<VehicleIcon3DArt>(['car', 'tanker'])

export interface VehicleIcon3DProps extends HTMLAttributes<HTMLSpanElement> {
  /**
   * Preset box — 'sm' = 39×29 list thumb, 'md' = 57×32.33 card art — or a
   * numeric art width in px (height follows the master aspect ratio).
   * @default 'md'
   */
  size?: VehicleIcon3DSize | number
  /** Which illustration to render. @default 'car' */
  art?: VehicleIcon3DArt
  /** Status tone for the badge dot. @default 'muted' */
  tone?: VehicleStatusTone
  /**
   * Status badge dot position: 'start' overlaps bottom-start (list rows),
   * 'end' overlaps bottom-end (card tile). Omitted/false = no badge.
   *
   * IGNORED for an `art` that isn't mobility-capable (see
   * `MOBILITY_CAPABLE_ART`) — a stationary asset (e.g. `'weather-station'`)
   * has no moving/idling/stopped status, so the mobility dot must never
   * render for it regardless of what a caller passes here. This is enforced
   * centrally in this component rather than trusted to every caller.
   */
  badge?: 'start' | 'end' | false
  /**
   * Accessible label (e.g. the vehicle id). Omitted → the icon is decorative
   * (`aria-hidden`).
   */
  label?: string
}

/** Master art geometry (Figma node 495:4149). */
const ART_W = 57.0437
const ART_H = 32.3287
const ART_VIEWBOX = `0 0 ${ART_W} ${ART_H}`

/**
 * Status dot fill — sampled from the designer's own list-thumbnail exports
 * (Figma 13:18867 `Group 1261154727/728/729`, the three status variants of
 * this exact icon): moving `#12B76A` = success-500, idling `#F79009` =
 * warning-500, stopped `#D92D20` = error-600. The three files differ ONLY in
 * this dot's fill — the tanker art itself is byte-identical across them,
 * which is why one art + a tone-driven badge is the right anatomy and three
 * separate assets would have been wrong.
 */
const TONE_DOT: Record<VehicleStatusTone, string> = {
  success: 'bg-success-scale-500',
  warning: 'bg-warning-scale-500',
  error: 'bg-error-600',
  // Non-Reporting = grey-400 (#98A2B3), SPEC §1 / visual finding #33.
  muted: 'bg-gray-400',
}

const TONE_GLYPH: Record<VehicleStatusTone, ReactNode> = {
  success: <Navigation className="size-2 fill-current" strokeWidth={0} />,
  warning: <Pause className="size-2 fill-current" strokeWidth={0} />,
  error: <Square className="size-2 fill-current" strokeWidth={0} />,
  muted: <Square className="size-2 fill-current" strokeWidth={0} />,
}

/**
 * WeatherStationArt (A24) — the designer's weather-mast illustration
 * (anemometer/vane/sensor box), a RASTER asset (unlike the vector car/tanker
 * art) at two embedded sizes (`weather-station-art.ts`); the browser picks
 * via `srcSet` so a card-sized tile still gets a crisp source instead of the
 * list thumb upscaled. Square aspect (`WEATHER_STATION_ART_ASPECT`).
 */
function WeatherStationArt({ width, height }: { width: number; height: number }) {
  return (
    <img
      src={WEATHER_STATION_ART_96}
      srcSet={`${WEATHER_STATION_ART_48} 48w, ${WEATHER_STATION_ART_96} 96w`}
      sizes={`${Math.round(width)}px`}
      width={width}
      height={height}
      alt=""
      aria-hidden="true"
      className="block object-contain"
      draggable={false}
    />
  )
}

