export const VehicleIcon3D = forwardRef<HTMLSpanElement, VehicleIcon3DProps>(
  function VehicleIcon3D(
    { size = 'md', art = 'car', tone = 'muted', badge = false, label, className, style, ...rest },
    ref,
  ) {
    // Box + art geometry per preset.
    let boxW: number
    let boxH: number
    let artW: number
    // Each art keeps its OWN aspect — the tanker is a different silhouette
    // from the master car (and the weather station is a square raster) and
    // must not be stretched into its box.
    const aspect =
      art === 'tanker' ? TANKER_H / TANKER_W : art === 'weather-station' ? 1 : ART_H / ART_W
    if (size === 'sm') {
      boxW = 39
      boxH = 29
      artW = 38.8182
    } else if (size === 'md') {
      boxW = ART_W
      artW = ART_W
      boxH = ART_W * aspect
    } else {
      artW = size
      boxW = size
      boxH = size * aspect
    }
    const artH = artW * aspect
    // Mobility badge never renders for a non-mobility art (see
    // `MOBILITY_CAPABLE_ART`) — e.g. `art="weather-station"`, a stationary
    // sensor, must never show the moving/idling/stopped dot no matter what
    // a caller passes as `badge`.
    const showBadge = MOBILITY_CAPABLE_ART.has(art) ? badge : false
    const badgePx = showBadge === 'end' ? 16 : 15

    return (
      <span
        ref={ref}
        role={label ? 'img' : undefined}
        aria-label={label}
        aria-hidden={label ? undefined : true}
        className={cn('relative inline-flex items-center justify-center', className)}
        style={{ width: boxW, height: boxH, ...style }}
        {...rest}
      >
        {art === 'tanker' ? (
          <TankerArt width={artW} height={artH} />
        ) : art === 'weather-station' ? (
          <WeatherStationArt width={artW} height={artH} />
        ) : (
          <VehicleArt width={artW} height={artH} />
        )}
        {showBadge ? (
          <span
            data-slot="vehicle-icon-3d-badge"
            className={cn(
              'absolute flex items-center justify-center rounded-full text-white ring-2 ring-white',
              TONE_DOT[tone],
            )}
            // Inline logical insets, not `-start-0.5`/`-end-1`: NEGATIVE logical
            // inset utilities are not reliably emitted by every consumer's
            // Tailwind build (a consumer scanning `@fams/ui-kit/dist` can get
            // `-bottom-1` but no `-end-1`, dropping the dot to its static
            // position). Inline logical properties still mirror under RTL.
            style={
              showBadge === 'end'
                ? { width: badgePx, height: badgePx, insetInlineEnd: -4, insetBlockEnd: -4 }
                : { width: badgePx, height: badgePx, insetInlineStart: -2, insetBlockEnd: -2 }
            }
          >
            {TONE_GLYPH[tone]}
          </span>
        ) : null}
      </span>
    )
  },
)
